CREATE FUNCTION population_top3000_202608_202609_v1.oq6_reason_ok(status0 int,body0 bytea,ticker0 text,reason0 text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='pg_catalog' AS $$
