 IF status0<>200 THEN RETURN reason0='HTTP_ERROR';END IF;
 BEGIN doc0:=convert_from(body0,'UTF8')::jsonb;EXCEPTION WHEN OTHERS THEN RETURN reason0='ENCODING_OR_JSON';END;
