LSE to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)') END),'UTF8')),'hex') AND lr.released_at IS NOT NULL AND lr.outcome='KNOWN_RESPONSE_RETAINED_QUALITY_HOLD' AND lr.received_bytes=octet_length(bs.body))
$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_population() RETURNS TABLE(points int,known_quality int,unknown int,unattempted int,next_ordinal int) LANGUAGE plpgsql STABLE SET search_path='pg_catalog' AS $$
DECLARE x record;pc int;kc int;cc int;source_ok boolean;po int:=0;ko int:=0;uo int:=0;no int:=0;nxt int:=201;
BEGIN
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_request)<>200 OR (SELECT count(DISTINCT ordinal) FROM population_top3000_202608_202609_v1.ov4_request)<>200 THEN RAISE EXCEPTION 'OQ6_EXACT_200_POPULATION_REQUIRED';END IF;
 FOR x IN SELECT * FROM population_top3000_202608_202609_v1.ov4_request ORDER BY ordinal LOOP
 SELECT (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_cap WHERE k=x.k)+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=x.k) INTO cc;
 SELECT (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_point WHERE k=x.k)+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_point WHERE k=x.k) INTO pc;
 SELECT count(*) INTO kc FROM population_top3000_202608_202609_v1.oq6_quality WHERE k=x.k;
 IF cc>1 OR pc>1 OR pc+kc>1 OR (cc=0 AND pc+kc>0) THEN RAISE EXCEPTION 'OQ6_INCONSISTENT_OVERLAPPING_POPULATION';END IF;
 IF kc=1 THEN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality q WHERE q.k=x.k AND q.sha=encode(sha256(convert_to(q.disposition::text,'UTF8')),'hex') AND q.disposition->>'absence_inferred'='false' AND q.disposition->>'inactive_inferred'='false' AND q.disposition->>'intervals_qualified'='false' AND q.disposition->>'family_accepted'='false' AND population_top3000_202608_202609_v1.oq6_known_ok(q.k,q.origin) AND q.disposition->>'continuation_eligible'=(CASE q.origin WHEN 'OLD' THEN (SELECT population_top3000_202608_202609_v1.oq6_continuable404(status,body) FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=q.k) ELSE (SELECT population_top3000_202608_202609_v1.oq6_continuable404(status,body) FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=q.k) END)::text AND q.source_sha=CASE q.origin WHEN 'OLD' THEN (SELECT sha FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=q.k) ELSE (SELECT sha FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=q.k) END) THEN RAISE EXCEPTION 'OQ6_KNOWN_DISPOSITION_LINEAGE_CHANGED';END IF;
 ko:=ko+1;IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality q WHERE q.k=x.k AND q.disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN nxt:=least(nxt,x.ordinal);END IF;
 ELSIF pc=1 THEN
 WITH cp AS(SELECT c.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_cap c WHERE k=x.k UNION ALL SELECT c.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_cap c WHERE k=x.k),bp AS(SELECT p.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_point p WHERE k=x.k UNION ALL SELECT p.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_point p WHERE k=x.k),bs AS(SELECT s.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_spool s WHERE k=x.k UNION ALL SELECT s.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_spool s WHERE k=x.k)
 SELECT EXISTS(SELECT 1 FROM cp JOIN bp USING(k,origin) JOIN bs USING(k,origin) JOIN population_top3000_202608_202609_v1.pipeline_attempt ar ON ar.attempt_id=cp.attempt_id JOIN population_top3000_202608_202609_v1.pipeline_commit cm ON cm.attempt_id=ar.attempt_id AND cm.task_id=ar.task_id JOIN population_top3000_202608_202609_v1.pipeline_task tr ON tr.task_id=ar.task_id WHERE ar.owner_fence=3 AND ar.stop_generation=1 AND tr.owner_fence=3 AND tr.stop_generation=1 AND tr.executions>=ar.execution_number AND tr.input_versions->>'worker'=cp.worker_sha AND tr.payload->>'execution_binding'='REVIEWED_PRIVATE_NATIVE_FUNCTION' AND ar.adapter_sha256=encode(sha256(convert_to(pg_get_functiondef(CASE cp.origin WHEN 'OLD' THEN 'population_top3000_202608_202609_v1.ov4_claim(bigint,text)'::regprocedure ELSE to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)') END),'UTF8')),'hex') AND bp.point->'request'=x.r AND bp.point->'case_refs'=x.case_refs AND bp.point->'source_record'=(convert_from(bs.body,'UTF8')::jsonb)->'results' AND bs.status=200 AND ar.outcome='COMPLETE' AND ar.ended_at IS NOT NULL AND ar.request_id IS NOT NULL AND cm.new_committed_units=1 AND cm.output_sha256=bp.sha AND bp.sha=encode(sha256(convert_to(bp.point::text,'UTF8')),'hex') AND bp.point->>'source_sha256'=bs.sha AND bp.point->>'request_sha256'=x.request_sha AND bs.sha=encode(sha256(bs.body),'hex') AND cm.receipt->>'source_sha256'=bs.sha AND cm.receipt->>'worker_sha256'=cp.worker_sha) INTO source_ok;
 IF NOT source_ok THEN RAISE EXCEPTION 'OQ6_POINT_COMMIT_SOURCE_LINEAGE_CHANGED';END IF;po:=po+1;
 ELSIF cc=1 THEN uo:=uo+1;nxt:=least(nxt,x.ordinal);
 ELSE no:=no+1;nxt:=least(nxt,x.ordinal);
 END IF;
 END LOOP;
 IF po+ko+uo+no<>200 THEN RAISE EXCEPTION 'OQ6_POPULATION_NOT_EXACT_200';END IF;
 RETURN QUERY SELECT po,ko,uo,no,nxt;
END;$$;

