 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>100 THEN RAISE EXCEPTION 'OQ6_CUMULATIVE_CLAIM_DISPATCH_BOUND';END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE event_id=pin.claim_id AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'assignment_event_id'=pin.assignment_id::text AND details->>'executor'='automation:6adc2c96db348191bca7cf4eacfdac32') THEN RAISE EXCEPTION 'OQ6_ENGINEERING_PROVENANCE_REQUIRED';END IF;
 IF (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND (relname LIKE 'oq6_%' OR relname LIKE 'ov4_%'))>33554432 THEN RAISE EXCEPTION 'OQ6_RELATION_BOUND';END IF;
 IF (SELECT budget_evidence#>>'{cohort_selection_policy,policy_sha256}' FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) IS DISTINCT FROM '3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb' THEN RAISE EXCEPTION 'OQ6_POLICY_CHANGED';END IF;
 IF population_top3000_202608_202609_v1.ov4_bundle()<>'acef899bc605a19a3af243152b4a24c9482a55e3c49a6072a417f989e394bc0b' THEN RAISE EXCEPTION 'OQ6_OLD_CODE_CHANGED';END IF;
 PERFORM population_top3000_202608_202609_v1.oq6_population();
 RETURN d;
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_seed(worker_sha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE aa jsonb;cc jsonb;rq record;disp jsonb;BEGIN
 PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT details INTO STRICT aa FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=49964 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
 SELECT details INTO STRICT cc FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=50296 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
 IF encode(sha256(convert_to(aa::text,'UTF8')),'hex')<>'8ebe540e3d91c9a803ec4d2949c9c4285c4c78e3d5aee69a8974a1981feb1a67' OR cc->>'assignment_event_id'<>'49964' OR (cc->>'expires_at')::timestamptz<=clock_timestamp() OR worker_sha!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'OQ6_CURRENT_EXACT_CLAIM_REQUIRED';END IF;
 IF population_top3000_202608_202609_v1.ov4_bundle()<>'acef899bc605a19a3af243152b4a24c9482a55e3c49a6072a417f989e394bc0b' OR (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_request)<>200 OR (SELECT encode(sha256(convert_to(jsonb_agg(r ORDER BY ordinal)::text,'UTF8')),'hex') FROM population_top3000_202608_202609_v1.ov4_request)<>'13dafeef5c83990b6c73f8c8d9a7edcbfd81bff22b2f3e268e38d26d5c863bef' THEN RAISE EXCEPTION 'OQ6_ORIGINAL_CODE_OR_200_PINS_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.oq6_pin VALUES(true,worker_sha,49964,50296,aa->>'input_manifest_sha256');
 SELECT * INTO STRICT rq FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=1;
 IF NOT population_top3000_202608_202609_v1.oq6_known_ok(rq.k,'OLD') OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=rq.k AND status=404 AND octet_length(body)=100 AND sha='857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa') THEN RAISE EXCEPTION 'OQ6_REVIEWED_OLD_404_LINEAGE_REQUIRED';END IF;
 disp:=jsonb_build_object('origin','OLD','kind','KNOWN_HTTP_RESPONSE_QUALITY_HOLD','http_status',404,'quality_reason','HTTP_ERROR','continuation_eligible',true,'source_sha256','857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa','reviewed_implementation_assignment',49964,'original_source_admission',49913,'original_source_claim',49857,'point_facts_qualified',false,'absence_inferred',false,'inactive_inferred',false,'intervals_qualified',false,'family_accepted',false);
 INSERT INTO population_top3000_202608_202609_v1.oq6_quality VALUES(rq.k,'OLD','857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa',disp,encode(sha256(convert_to(disp::text,'UTF8')),'hex'));
 PERFORM population_top3000_202608_202609_v1.oq6_population();
 RETURN '{"state":"RETAINED_404_DISPOSITION_APPENDED_ONLY","requests":200,"known_quality":1,"unattempted":199,"source_calls":0,"old_rows_changed":false}'::jsonb;
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_preflight(aid bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='pg_catalog' AS $$
DECLARE b record;r record;BEGIN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton AND a.enabled AND NOT a.stopped AND a.hold_reason IS NULL AND p.enabled AND a.owner_id='top3000-completion-20261024-root-5db48b32d103' AND a.owner_fence=3 AND a.stop_generation=1 AND a.admitted_until>clock_timestamp() AND p.deadline>clock_timestamp() AND p.tick_count<p.max_ticks) THEN RETURN '{"state":"QUIET_CONTROL_WAIT"}'::jsonb;END IF;
 SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid;
 IF FOUND AND b.checkpoint=201 THEN RETURN '{"state":"COMPLETE"}'::jsonb;END IF;
 SELECT * INTO r FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=coalesce(b.checkpoint,1);
 IF r.k IS NULL THEN RETURN '{"state":"UNSEEDED"}'::jsonb;END IF;
 RETURN jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=r.k) THEN 'BODY_RETAINED' WHEN EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=r.k) THEN 'EXISTING_ATTEMPT_HELD_NO_REISSUE' ELSE 'ELIGIBLE' END,'request_key',r.k);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_claim(aid bigint,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;a record;p record;b record;r record;tid uuid;at uuid;tok text;pin record;taskrow record;ex bigint;BEGIN
 IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RETURN '{"state":"BUSY"}'::jsonb;END IF;
 d:=population_top3000_202608_202609_v1.oq6_guard(aid); -- Controls are always first.
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
 IF (d->>'not_after')::timestamptz<=clock_timestamp()+interval '45 seconds' THEN RETURN '{"state":"QUIET_SOURCE_TIME_BOUND"}'::jsonb;END IF;
 SELECT * INTO STRICT pin FROM population_top3000_202608_202609_v1.oq6_pin WHERE id;
 IF wsha IS DISTINCT FROM pin.worker_sha THEN RAISE EXCEPTION 'OQ6_DEPLOYED_CODE_CHANGED';END IF;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
 IF a.next_provider_at>clock_timestamp() OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_job WHERE status='LEASED' AND lease_until>clock_timestamp()) THEN RETURN '{"state":"QUIET_SHARED_PROVIDER_WAIT"}'::jsonb;END IF;
 SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_START_REQUIRED';END IF;
 IF b.checkpoint=201 THEN RETURN '{"state":"COMPLETE"}'::jsonb;END IF;
 SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=b.checkpoint;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(r.case_refs) q(cp) WHERE NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 ap WHERE ap.content->>'company_id'=cp->>'company_id' AND ap.ticker=r.r->>'ticker' AND ap.point_date=DATE '2026-08-03' AND ap.eligible AND ap.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND ap.record_sha256=cp->>'expected_anchor_sha' AND ap.record_sha256=encode(sha256(convert_to(ap.content::text,'UTF8')),'hex'))) THEN RAISE EXCEPTION 'OQ6_STALE_COMPANY_ANCHOR_PIN';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ov4_cap WHERE k=r.k) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=r.k) THEN RETURN jsonb_build_object('state','EXISTING_ATTEMPT_HELD_NO_REISSUE','request_key',r.k);END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cp JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=cp.admission WHERE e.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=100 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_SOURCE_BOUND"}'::jsonb;END IF;
 IF (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND (relname LIKE 'oq6_%' OR relname LIKE 'ov4_%'))+3145728>33554432 THEN RETURN '{"state":"FINITE_RELATION_WAIT"}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cc JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=cc.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=200 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_HTTP_BOUND"}'::jsonb;END IF;
 IF a.provider_requests>=a.max_provider_requests OR a.http_invocations>=a.max_http_invocations OR a.stored_bytes+a.reserved_bytes+1048576>a.max_source_bytes OR (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE admission=aid)>=100 OR ((SELECT bytes FROM population_top3000_202608_202609_v1.oq6_spool_budget WHERE id)+(SELECT coalesce(sum(octet_length(body)),0) FROM population_top3000_202608_202609_v1.ov4_spool)+(SELECT coalesce(sum(l.reserved_bytes),0) FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.oq6_cap c USING(attempt_id) WHERE l.released_at IS NULL)+1048576)>33554432 OR (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m'))+3145728>=(p.budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint THEN RETURN '{"state":"FINITE_RESOURCE_WAIT"}'::jsonb;END IF;
 SELECT * INTO STRICT taskrow FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=b.task_id FOR UPDATE;
 IF taskrow.status<>'BLOCKED' OR taskrow.executions>=taskrow.max_executions OR b.last_request_id IS NULL THEN RAISE EXCEPTION 'OQ6_NATIVE_TASK_EXECUTION_OR_DISPATCH_REQUIRED';END IF;
 IF taskrow.blocker_code='OQ6_RETAINED_SOURCE_QUALITY_HOLD' THEN
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task tt JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=(tt.payload->>'oq6_admission')::bigint WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=(SELECT least(50,(se.details->>'maximum_new_tasks')::int) FROM population_top3000_202608_202609_v1.pipeline_event se JOIN population_top3000_202608_202609_v1.pipeline_event ce ON se.event_id=(ce.details->>'assignment_event_id')::bigint WHERE ce.event_id=(d->>'execution_claim_event_id')::bigint) THEN RETURN '{"state":"FINITE_NEW_TASK_BOUND"}'::jsonb;END IF;
 tid:=gen_random_uuid();
 INSERT INTO population_top3000_202608_202609_v1.pipeline_task(task_id,operation_key,family_id,stage,partition_key,payload,input_versions,status,max_executions,blocker_code,resumption_condition) VALUES(tid,'oq6:'||aid||':after-quality:'||b.checkpoint,'REF01','ACQUIRE','oq6-private-native:'||aid||':'||b.checkpoint,jsonb_build_object('source_admission',aid,'oq6_admission',aid,'execution_binding','REVIEWED_PRIVATE_NATIVE_FUNCTION'),taskrow.input_versions,'BLOCKED',100,'OQ6_PRIVATE_NATIVE_ROUTE','{"route":"oq6_wake"}');
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET task_id=tid WHERE admission=aid;SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid;SELECT * INTO taskrow FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid FOR UPDATE;
 END IF;
 ex:=taskrow.executions+1;
 at:=gen_random_uuid();tok:=gen_random_uuid()::text||gen_random_uuid()::text;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256,request_id) VALUES(at,b.task_id,ex,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)')),'UTF8')),'hex'),b.last_request_id);
 INSERT INTO population_top3000_202608_202609_v1.oq6_cap VALUES(r.k,at,aid,encode(sha256(convert_to(tok,'UTF8')),'hex'),wsha,clock_timestamp());
 INSERT INTO population_top3000_202608_202609_v1.pipeline_provider_lease(attempt_id,provider,reserved_bytes,reserved_usd) VALUES(at,'Massive',1048576,0);
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=at,lease_until=least(clock_timestamp()+interval '90 seconds',(d->>'not_after')::timestamptz),executions=ex,owner_fence=3,stop_generation=1,started_at=coalesce(started_at,clock_timestamp()) WHERE task_id=b.task_id;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET provider_requests=provider_requests+1,http_invocations=http_invocations+1,reserved_bytes=reserved_bytes+1048576,next_provider_at=clock_timestamp()+interval '15 seconds' WHERE singleton;
 RETURN jsonb_build_object('state','CLAIMED','token',tok,'request',r.r||jsonb_build_object('request_key',r.k,'request_manifest_sha256',d->>'request_manifest_sha256','scope_sha256',d->>'scope_sha256','request_state','ADMITTED'));
END;$$;
-- Independent committed RPC: no control, task, attempt or provider-lease lock.
-- Capability permits only retaining the already reserved response. It cannot issue HTTP,
-- release reservations, normalize, advance a task or qualify facts.
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_spool_save(k0 text,tok text,receipt text,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE c record;j jsonb;b bytea;h text;n int;old record;BEGIN
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.oq6_pin pin WHERE a.singleton AND p.singleton AND pin.id AND a.owner_id='top3000-completion-20261024-root-5db48b32d103' AND a.owner_fence=3 AND a.stop_generation=1 AND a.enabled AND NOT a.stopped AND a.hold_reason IS NULL AND p.enabled AND p.deadline>clock_timestamp() AND a.admitted_until>clock_timestamp() AND p.expected_owner_id=a.owner_id AND p.expected_owner_fence=3 AND p.expected_stop_generation=1 AND a.scope_sha256=p.scope_sha256 AND a.scope_sha256='8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' AND p.budget_evidence#>>'{cohort_selection_policy,policy_sha256}'='3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb' AND pin.worker_sha=wsha AND pin.worker_sha=c.worker_sha) THEN RAISE EXCEPTION 'OQ6_SPOOL_CURRENT_OWNER_STOP_POLICY_CODE_REQUIRED';END IF;
 IF c.token_sha IS DISTINCT FROM encode(sha256(convert_to(tok,'UTF8')),'hex') OR c.worker_sha IS DISTINCT FROM wsha THEN RAISE EXCEPTION 'OQ6_SPOOL_CAPABILITY_REJECTED';END IF;
 IF octet_length(receipt)>1500000 THEN RAISE EXCEPTION 'OQ6_RECEIPT_BOUND';END IF;j:=receipt::jsonb;b:=decode(j->>'body_base64','base64');n:=octet_length(b);h:=encode(sha256(b),'hex');
 IF n>1048576 OR j->>'sha256' IS DISTINCT FROM h OR j->>'bytes' IS DISTINCT FROM n::text OR j->>'physical_http_count' IS DISTINCT FROM '1' OR j->>'representation' IS DISTINCT FROM 'FETCH_RESPONSE_BODY_BYTES_NOT_ORIGINAL_HTTP_WIRE' THEN RAISE EXCEPTION 'OQ6_SOURCE_HASH_OR_BOUND_REJECTED';END IF;
 PERFORM 1 FROM population_top3000_202608_202609_v1.oq6_spool_budget WHERE id FOR UPDATE;
 SELECT * INTO old FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=k0;
 IF FOUND THEN IF old.body IS DISTINCT FROM b OR old.receipt IS DISTINCT FROM j-'body_base64' THEN RAISE EXCEPTION 'OQ6_IMMUTABLE_SPOOL_CONFLICT';END IF;RETURN jsonb_build_object('state','BODY_ALREADY_RETAINED','sha256',h);END IF;
 UPDATE population_top3000_202608_202609_v1.oq6_spool_budget SET bytes=bytes+n WHERE id AND bytes+n<=33554432;IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_SPOOL_CUMULATIVE_BOUND';END IF;
 INSERT INTO population_top3000_202608_202609_v1.oq6_spool VALUES(k0,b,h,(j->>'http_status')::int,j-'body_base64',clock_timestamp());
 RETURN jsonb_build_object('state','BODY_RETAINED','sha256',h,'original_historical_receipt_proven',false);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_consume(k0 text,aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;c record;s record;r record;a record;t record;b record;l record;doc jsonb;v jsonb;h text;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0 AND admission=aid;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE attempt_id=c.attempt_id FOR UPDATE;
 IF a.outcome='COMPLETE' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_point p JOIN population_top3000_202608_202609_v1.pipeline_commit m ON m.attempt_id=a.attempt_id AND m.output_sha256=p.sha WHERE p.k=k0 AND p.sha=encode(sha256(convert_to(p.point::text,'UTF8')),'hex')) THEN RETURN jsonb_build_object('state','POINT_ALREADY_RETAINED','request_key',k0);END IF;
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=a.task_id FOR UPDATE;
 IF a.outcome='BLOCKED' AND t.blocker_code='OQ6_RETAINED_SOURCE_QUALITY_HOLD' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease lease_row WHERE lease_row.attempt_id=a.attempt_id AND lease_row.released_at IS NOT NULL AND lease_row.outcome='KNOWN_RESPONSE_RETAINED_QUALITY_HOLD') THEN RETURN '{"state":"BODY_RETAINED_QUALITY_ALREADY_SETTLED","automatic_retry":false,"no_listing_inferred":false}'::jsonb;END IF;
 IF a.adapter_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)')),'UTF8')),'hex') OR a.owner_fence<>3 OR a.stop_generation<>1 OR t.attempt_id IS DISTINCT FROM a.attempt_id OR a.execution_number IS DISTINCT FROM t.executions OR t.lease_until IS NULL OR t.lease_until<=clock_timestamp() OR a.request_id IS NULL OR c.worker_sha IS DISTINCT FROM d->>'worker_sha256' THEN RAISE EXCEPTION 'OQ6_ATTEMPT_TASK_CODE_BINDING';END IF;
 SELECT * INTO STRICT s FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=k0;
 SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.ov4_request WHERE k=k0;
 IF s.sha IS DISTINCT FROM encode(sha256(s.body),'hex') THEN RAISE EXCEPTION 'OQ6_SOURCE_CHANGED';END IF;
 IF a.outcome='COMPLETE' THEN RETURN jsonb_build_object('state','POINT_ALREADY_RETAINED','request_key',k0);END IF;
 IF a.outcome<>'RUNNING' OR t.status<>'LEASED' THEN RAISE EXCEPTION 'OQ6_ATTEMPT_NOT_RUNNING';END IF;
 IF s.status<>200 THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'HTTP_ERROR');END IF;
 BEGIN doc:=convert_from(s.body,'UTF8')::jsonb;EXCEPTION WHEN OTHERS THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'ENCODING_OR_JSON');END;
 IF doc->>'status' IS DISTINCT FROM 'OK' OR jsonb_typeof(doc->'results') IS DISTINCT FROM 'object' OR doc#>>'{results,ticker}' IS DISTINCT FROM r.r->>'ticker' OR nullif(doc->>'next_url','') IS NOT NULL THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'IDENTITY_OR_STATUS');END IF;
 v:=jsonb_build_object('request',r.r,'case_refs',r.case_refs,'source_record',doc->'results','source_sha256',s.sha,'request_sha256',r.request_sha,'evidence_semantics','DATE_QUALIFIED_VENDOR_OVERVIEW_POINT_NOT_INTERVAL_V6','original_historical_receipt_proven',false,'intervals_qualified',false,'family_accepted',false);h:=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 INSERT INTO population_top3000_202608_202609_v1.oq6_point VALUES(k0,v,h);
 SELECT * INTO STRICT l FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE attempt_id=a.attempt_id AND released_at IS NULL FOR UPDATE;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET reserved_bytes=reserved_bytes-l.reserved_bytes,stored_bytes=stored_bytes+octet_length(s.body) WHERE singleton AND reserved_bytes>=l.reserved_bytes;IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_COUNTER_RESERVATION_MISMATCH';END IF;
 UPDATE population_top3000_202608_202609_v1.pipeline_provider_lease SET released_at=clock_timestamp(),received_bytes=octet_length(s.body),outcome='NATIVE_SINGLE_HTTP_BODY_RETAINED' WHERE attempt_id=a.attempt_id;
