CREATE FUNCTION population_top3000_202608_202609_v1.oq6_dispatch(aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;b record;rid bigint;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid FOR UPDATE;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=100 THEN RETURN '{"state":"FINITE_CLAIM_DISPATCH_BOUND"}'::jsonb;END IF;
 IF b.checkpoint=201 OR b.wake_ordinal>=b.checkpoint OR b.dispatches>=100 OR (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE admission=aid)>=100 THEN RETURN '{"state":"FINITE_TRANCHE_COMPLETE_OR_HELD","automatic_retry":false}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cc JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=cc.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=200 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_HTTP_BOUND"}'::jsonb;END IF;
 IF (SELECT http_invocations>=max_http_invocations FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) THEN RETURN '{"state":"HTTP_CAP_HELD"}'::jsonb;END IF;
 SELECT net.http_post(url:='https://oxzabweahkoimtevbbny.supabase.co/functions/v1/population-top3000-overview-v6',headers:='{"Content-Type":"application/json"}'::jsonb,body:=jsonb_build_object('admission_event_id',aid,'wake_token',b.wake_token),timeout_milliseconds:=55000) INTO rid;
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET dispatches=dispatches+1,wake_ordinal=checkpoint,last_request_id=rid WHERE admission=aid;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET http_invocations=http_invocations+1 WHERE singleton;
 RETURN jsonb_build_object('state','ASYNC','request_id',rid,'dispatch_http',1,'provider_http',0);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_wake(aid bigint,tok text,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
