 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
