CREATE FUNCTION population_top3000_202608_202609_v1.oq6_known_ok(k0 text,origin0 text) RETURNS boolean LANGUAGE sql STABLE SET search_path='pg_catalog' AS $$
WITH caps AS(SELECT 'OLD' origin,c.* FROM population_top3000_202608_202609_v1.ov4_cap c UNION ALL SELECT 'NEW',c.* FROM population_top3000_202608_202609_v1.oq6_cap c),spools AS(SELECT 'OLD' origin,s.* FROM population_top3000_202608_202609_v1.ov4_spool s UNION ALL SELECT 'NEW',s.* FROM population_top3000_202608_202609_v1.oq6_spool s)
SELECT EXISTS(SELECT 1 FROM caps cp JOIN spools bs ON bs.k=cp.k AND bs.origin=cp.origin JOIN population_top3000_202608_202609_v1.ov4_request rq ON rq.k=cp.k JOIN population_top3000_202608_202609_v1.pipeline_attempt ar ON ar.attempt_id=cp.attempt_id JOIN population_top3000_202608_202609_v1.pipeline_task tr ON tr.task_id=ar.task_id JOIN population_top3000_202608_202609_v1.pipeline_provider_lease lr ON lr.attempt_id=ar.attempt_id WHERE cp.k=k0 AND cp.origin=origin0 AND bs.sha=encode(sha256(bs.body),'hex') AND bs.receipt->>'sha256'=bs.sha AND bs.receipt->>'bytes'=octet_length(bs.body)::text AND bs.receipt->>'http_status'=bs.status::text AND bs.receipt->>'physical_http_count'='1' AND rq.request_sha=encode(sha256(convert_to(rq.r::text,'UTF8')),'hex') AND ar.outcome='BLOCKED' AND ar.ended_at IS NOT NULL AND ar.request_id IS NOT NULL AND ar.owner_fence=3 AND ar.stop_generation=1 AND ar.execution_number=tr.executions AND tr.attempt_id=ar.attempt_id AND tr.status='BLOCKED' AND tr.lease_until IS NULL AND tr.owner_fence=3 AND tr.stop_generation=1 AND tr.blocker_code=CASE origin0 WHEN 'OLD' THEN 'OV4_RETAINED_SOURCE_QUALITY_HOLD' ELSE 'OQ6_RETAINED_SOURCE_QUALITY_HOLD' END AND tr.resumption_condition->>'request_key'=cp.k AND population_top3000_202608_202609_v1.oq6_reason_ok(bs.status,bs.body,rq.r->>'ticker',tr.resumption_condition->>'quality_reason') AND tr.resumption_condition->>'source_sha256'=bs.sha AND tr.payload->>'source_admission'=cp.admission::text AND tr.input_versions->>'worker'=cp.worker_sha AND tr.input_versions->>'manifest'='13dafeef5c83990b6c73f8c8d9a7edcbfd81bff22b2f3e268e38d26d5c863bef' AND cp.worker_sha=CASE origin0 WHEN 'OLD' THEN (SELECT worker_sha FROM population_top3000_202608_202609_v1.ov4_pin WHERE id) ELSE (SELECT worker_sha FROM population_top3000_202608_202609_v1.oq6_pin WHERE id) END AND ar.adapter_sha256=encode(sha256(convert_to(pg_get_functiondef(CASE origin0 WHEN 'OLD' THEN 'population_top3000_202608_202609_v1.ov4_claim(bigint,text)'::regprocedure ELSE to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)') END),'UTF8')),'hex') AND lr.released_at IS NOT NULL AND lr.outcome='KNOWN_RESPONSE_RETAINED_QUALITY_HOLD' AND lr.received_bytes=octet_length(bs.body))
$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_population() RETURNS TABLE(points int,known_quality int,unknown int,unattempted int,next_ordinal int) LANGUAGE plpgsql STABLE SET search_path='pg_catalog' AS $$
DECLARE x record;pc int;kc int;cc int;source_ok boolean;po int:=0;ko int:=0;uo int:=0;no int:=0;nxt int:=201;
BEGIN
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_request)<>200 OR (SELECT count(DISTINCT ordinal) FROM population_top3000_202608_202609_v1.ov4_request)<>200 THEN RAISE EXCEPTION 'OQ6_EXACT_200_POPULATION_REQUIRED';END IF;
 FOR x IN SELECT * FROM population_top3000_202608_202609_v1.ov4_request ORDER BY ordinal LOOP
 SELECT (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_cap WHERE k=x.k)+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=x.k) INTO cc;
 SELECT (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_point WHERE k=x.k)+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_point WHERE k=x.k) INTO pc;
 SELECT count(*) INTO kc FROM population_top3000_202608_202609_v1.oq6_quality WHERE k=x.k;
 IF cc>1 OR pc>1 OR pc+kc>1 OR (cc=0 AND pc+kc>0) THEN RAISE EXCEPTION 'OQ6_INCONSISTENT_OVERLAPPING_POPULATION';END IF;
 IF kc=1 THEN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality q WHERE q.k=x.k AND q.sha=encode(sha256(convert_to(q.disposition::text,'UTF8')),'hex') AND q.disposition->>'absence_inferred'='false' AND q.disposition->>'inactive_inferred'='false' AND q.disposition->>'intervals_qualified'='false' AND q.disposition->>'family_accepted'='false' AND population_top3000_202608_202609_v1.oq6_known_ok(q.k,q.origin) AND q.disposition->>'continuation_eligible'=(CASE q.origin WHEN 'OLD' THEN (SELECT population_top3000_202608_202609_v1.oq6_continuable404(status,body) FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=q.k) ELSE (SELECT population_top3000_202608_202609_v1.oq6_continuable404(status,body) FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=q.k) END)::text AND q.source_sha=CASE q.origin WHEN 'OLD' THEN (SELECT sha FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=q.k) ELSE (SELECT sha FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=q.k) END) THEN RAISE EXCEPTION 'OQ6_KNOWN_DISPOSITION_LINEAGE_CHANGED';END IF;
 ko:=ko+1;IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality q WHERE q.k=x.k AND q.disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN nxt:=least(nxt,x.ordinal);END IF;
 ELSIF pc=1 THEN
 WITH cp AS(SELECT c.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_cap c WHERE k=x.k UNION ALL SELECT c.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_cap c WHERE k=x.k),bp AS(SELECT p.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_point p WHERE k=x.k UNION ALL SELECT p.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_point p WHERE k=x.k),bs AS(SELECT s.*, 'OLD' origin FROM population_top3000_202608_202609_v1.ov4_spool s WHERE k=x.k UNION ALL SELECT s.*, 'NEW' FROM population_top3000_202608_202609_v1.oq6_spool s WHERE k=x.k)
 SELECT EXISTS(SELECT 1 FROM cp JOIN bp USING(k,origin) JOIN bs USING(k,origin) JOIN population_top3000_202608_202609_v1.pipeline_attempt ar ON ar.attempt_id=cp.attempt_id JOIN population_top3000_202608_202609_v1.pipeline_commit cm ON cm.attempt_id=ar.attempt_id AND cm.task_id=ar.task_id JOIN population_top3000_202608_202609_v1.pipeline_task tr ON tr.task_id=ar.task_id WHERE ar.owner_fence=3 AND ar.stop_generation=1 AND tr.owner_fence=3 AND tr.stop_generation=1 AND tr.executions>=ar.execution_number AND tr.input_versions->>'worker'=cp.worker_sha AND tr.payload->>'execution_binding'='REVIEWED_PRIVATE_NATIVE_FUNCTION' AND ar.adapter_sha256=encode(sha256(convert_to(pg_get_functiondef(CASE cp.origin WHEN 'OLD' THEN 'population_top3000_202608_202609_v1.ov4_claim(bigint,text)'::regprocedure ELSE to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)') END),'UTF8')),'hex') AND bp.point->'request'=x.r AND bp.point->'case_refs'=x.case_refs AND bp.point->'source_record'=(convert_from(bs.body,'UTF8')::jsonb)->'results' AND bs.status=200 AND ar.outcome='COMPLETE' AND ar.ended_at IS NOT NULL AND ar.request_id IS NOT NULL AND cm.new_committed_units=1 AND cm.output_sha256=bp.sha AND bp.sha=encode(sha256(convert_to(bp.point::text,'UTF8')),'hex') AND bp.point->>'source_sha256'=bs.sha AND bp.point->>'request_sha256'=x.request_sha AND bs.sha=encode(sha256(bs.body),'hex') AND cm.receipt->>'source_sha256'=bs.sha AND cm.receipt->>'worker_sha256'=cp.worker_sha) INTO source_ok;
 IF NOT source_ok THEN RAISE EXCEPTION 'OQ6_POINT_COMMIT_SOURCE_LINEAGE_CHANGED';END IF;po:=po+1;
 ELSIF cc=1 THEN uo:=uo+1;nxt:=least(nxt,x.ordinal);
 ELSE no:=no+1;nxt:=least(nxt,x.ordinal);
 END IF;
 END LOOP;
 IF po+ko+uo+no<>200 THEN RAISE EXCEPTION 'OQ6_POPULATION_NOT_EXACT_200';END IF;
 RETURN QUERY SELECT po,ko,uo,no,nxt;
END;$$;

CREATE FUNCTION population_top3000_202608_202609_v1.oq6_bundle() RETURNS text LANGUAGE sql STABLE SET search_path='pg_catalog' AS $$SELECT encode(sha256(convert_to(string_agg(proname||':'||pg_get_functiondef(oid),E'\n' ORDER BY proname),'UTF8')),'hex') FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE 'oq6_%'$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_guard(aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE c jsonb;d jsonb;rv jsonb;pin record;sc jsonb;sa jsonb;BEGIN
 c:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT * INTO STRICT pin FROM population_top3000_202608_202609_v1.oq6_pin WHERE id;
 SELECT details INTO d FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=aid AND event='REF01_OVERVIEW_FINITE_SOURCE_ADMITTED_V6';
 SELECT details INTO rv FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=(d->>'review_event_id')::bigint AND event='REF01_OVERVIEW_FINITE_SOURCE_REVIEW_V6';
 IF d IS NULL OR rv IS NULL OR rv->>'approved' IS DISTINCT FROM 'true' OR rv->>'producer' IS NOT DISTINCT FROM rv->>'reviewer' OR nullif(rv->>'reviewer','') IS NULL OR rv->>'proposal_sha256' IS DISTINCT FROM encode(sha256(convert_to((d-'review_event_id')::text,'UTF8')),'hex') OR d->>'worker_sha256' IS DISTINCT FROM pin.worker_sha OR d->>'bundle_sha256' IS DISTINCT FROM population_top3000_202608_202609_v1.oq6_bundle() OR d->>'request_manifest_sha256' IS DISTINCT FROM '13dafeef5c83990b6c73f8c8d9a7edcbfd81bff22b2f3e268e38d26d5c863bef' OR d->>'input_manifest_sha256' IS DISTINCT FROM pin.input_sha OR d->>'owner_id' IS DISTINCT FROM c->>'owner_id' OR d->>'owner_fence' IS DISTINCT FROM '3' OR d->>'stop_generation' IS DISTINCT FROM '1' OR d->>'scope_sha256' IS DISTINCT FROM c->>'scope_sha256' OR d->>'not_after' IS NULL OR (d->>'not_after')::timestamptz<=clock_timestamp() OR d->>'max_provider_calls' IS DISTINCT FROM '100' OR d->>'max_http_calls' IS DISTINCT FROM '200' OR d->>'max_source_bytes' IS DISTINCT FROM '33554432' OR d->>'max_relation_bytes' IS DISTINCT FROM '33554432' OR d->>'automatic_retry' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'OQ6_REVIEWED_FINITE_ADMISSION_REQUIRED';END IF;

 SELECT details INTO sc FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=(d->>'execution_claim_event_id')::bigint AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
 SELECT details INTO sa FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=(sc->>'assignment_event_id')::bigint AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
 IF sc IS NULL OR sa IS NULL OR sc->>'executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR sc->>'authority_event_id' IS DISTINCT FROM '9528' OR sa->>'authority_event_id' IS DISTINCT FROM '9528' OR sa->>'root_will_not_concurrently_modify' IS DISTINCT FROM 'true' OR sa->>'assigned_executor' IS DISTINCT FROM sc->>'executor' OR sc->>'owner_id' IS DISTINCT FROM c->>'owner_id' OR sc->>'owner_fence' IS DISTINCT FROM '3' OR sc->>'stop_generation' IS DISTINCT FROM '1' OR sc->>'scope_sha256' IS DISTINCT FROM c->>'scope_sha256' OR sa->>'owner_id' IS DISTINCT FROM sc->>'owner_id' OR sa->>'owner_fence' IS DISTINCT FROM '3' OR sa->>'stop_generation' IS DISTINCT FROM '1' OR sa->>'scope_sha256' IS DISTINCT FROM sc->>'scope_sha256' OR sc->>'expires_at' IS NULL OR (sc->>'expires_at')::timestamptz<=clock_timestamp() OR (d->>'not_after')::timestamptz>(sc->>'expires_at')::timestamptz OR sa->>'not_after' IS NULL OR (d->>'not_after')::timestamptz>(sa->>'not_after')::timestamptz OR sc->>'assignment_details_sha256' IS DISTINCT FROM encode(sha256(convert_to(sa::text,'UTF8')),'hex') OR sa->>'kind' IS DISTINCT FROM 'EXACT200_HISTORICAL_OVERVIEW_FINITE_SOURCE_EXECUTION_V6' OR sa->>'input_manifest_sha256' IS DISTINCT FROM pin.input_sha OR coalesce((sa->>'maximum_new_tasks')::int,0) NOT BETWEEN 1 AND 50 OR coalesce((sa->>'maximum_native_dispatches')::int,0)<>100 OR coalesce((sa->>'new_provider_requests')::int,0)<100 OR coalesce((sa->>'maximum_http_invocations')::int,0)<200 OR coalesce((sa->>'maximum_source_bytes')::bigint,0)<33554432 OR coalesce((sa->>'maximum_additional_relation_bytes')::bigint,0)<33554432 OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'=d->>'execution_claim_event_id') THEN RAISE EXCEPTION 'OQ6_ACTIVE_EXACT_FINITE_SOURCE_EXECUTION_CLAIM_REQUIRED';END IF;

 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cp JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=cp.admission WHERE e.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>(sa->>'new_provider_requests')::int OR (SELECT coalesce(sum(b.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch b JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=b.admission WHERE e.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cp JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=cp.admission WHERE e.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>(sa->>'maximum_http_invocations')::int THEN RAISE EXCEPTION 'OQ6_CUMULATIVE_EXECUTION_CLAIM_CALL_BOUND';END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>100 THEN RAISE EXCEPTION 'OQ6_CUMULATIVE_CLAIM_DISPATCH_BOUND';END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE event_id=pin.claim_id AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'assignment_event_id'=pin.assignment_id::text AND details->>'executor'='automation:6adc2c96db348191bca7cf4eacfdac32') THEN RAISE EXCEPTION 'OQ6_ENGINEERING_PROVENANCE_REQUIRED';END IF;
 IF (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND (relname LIKE 'oq6_%' OR relname LIKE 'ov4_%'))>33554432 THEN RAISE EXCEPTION 'OQ6_RELATION_BOUND';END IF;
 IF (SELECT budget_evidence#>>'{cohort_selection_policy,policy_sha256}' FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton) IS DISTINCT FROM '3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb' THEN RAISE EXCEPTION 'OQ6_POLICY_CHANGED';END IF;
 IF population_top3000_202608_202609_v1.ov4_bundle()<>'acef899bc605a19a3af243152b4a24c9482a55e3c49a6072a417f989e394bc0b' THEN RAISE EXCEPTION 'OQ6_OLD_CODE_CHANGED';END IF;
 PERFORM population_top3000_202608_202609_v1.oq6_population();
 RETURN d;
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_seed(worker_sha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE aa jsonb;cc jsonb;rq record;disp jsonb;BEGIN
 PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
 SELECT details INTO STRICT aa FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=49964 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
 SELECT details INTO STRICT cc FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=50296 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
 IF encode(sha256(convert_to(aa::text,'UTF8')),'hex')<>'8ebe540e3d91c9a803ec4d2949c9c4285c4c78e3d5aee69a8974a1981feb1a67' OR cc->>'assignment_event_id'<>'49964' OR (cc->>'expires_at')::timestamptz<=clock_timestamp() OR worker_sha!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'OQ6_CURRENT_EXACT_CLAIM_REQUIRED';END IF;
 IF population_top3000_202608_202609_v1.ov4_bundle()<>'acef899bc605a19a3af243152b4a24c9482a55e3c49a6072a417f989e394bc0b' OR (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_request)<>200 OR (SELECT encode(sha256(convert_to(jsonb_agg(r ORDER BY ordinal)::text,'UTF8')),'hex') FROM population_top3000_202608_202609_v1.ov4_request)<>'13dafeef5c83990b6c73f8c8d9a7edcbfd81bff22b2f3e268e38d26d5c863bef' THEN RAISE EXCEPTION 'OQ6_ORIGINAL_CODE_OR_200_PINS_CHANGED';END IF;
 INSERT INTO population_top3000_202608_202609_v1.oq6_pin VALUES(true,worker_sha,49964,50296,aa->>'input_manifest_sha256');
 SELECT * INTO STRICT rq FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=1;
 IF NOT population_top3000_202608_202609_v1.oq6_known_ok(rq.k,'OLD') OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ov4_spool WHERE k=rq.k AND status=404 AND octet_length(body)=100 AND sha='857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa') THEN RAISE EXCEPTION 'OQ6_REVIEWED_OLD_404_LINEAGE_REQUIRED';END IF;
 disp:=jsonb_build_object('origin','OLD','kind','KNOWN_HTTP_RESPONSE_QUALITY_HOLD','http_status',404,'quality_reason','HTTP_ERROR','continuation_eligible',true,'source_sha256','857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa','reviewed_implementation_assignment',49964,'original_source_admission',49913,'original_source_claim',49857,'point_facts_qualified',false,'absence_inferred',false,'inactive_inferred',false,'intervals_qualified',false,'family_accepted',false);
 INSERT INTO population_top3000_202608_202609_v1.oq6_quality VALUES(rq.k,'OLD','857659202dcef4da139dbeecf0b47f0579654199e7652ecc1fdf90749107f9fa',disp,encode(sha256(convert_to(disp::text,'UTF8')),'hex'));
 PERFORM population_top3000_202608_202609_v1.oq6_population();
 RETURN '{"state":"RETAINED_404_DISPOSITION_APPENDED_ONLY","requests":200,"known_quality":1,"unattempted":199,"source_calls":0,"old_rows_changed":false}'::jsonb;
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_preflight(aid bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='pg_catalog' AS $$
DECLARE b record;r record;BEGIN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton AND a.enabled AND NOT a.stopped AND a.hold_reason IS NULL AND p.enabled AND a.owner_id='top3000-completion-20261024-root-5db48b32d103' AND a.owner_fence=3 AND a.stop_generation=1 AND a.admitted_until>clock_timestamp() AND p.deadline>clock_timestamp() AND p.tick_count<p.max_ticks) THEN RETURN '{"state":"QUIET_CONTROL_WAIT"}'::jsonb;END IF;
 SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid;
 IF FOUND AND b.checkpoint=201 THEN RETURN '{"state":"COMPLETE"}'::jsonb;END IF;
 SELECT * INTO r FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=coalesce(b.checkpoint,1);
 IF r.k IS NULL THEN RETURN '{"state":"UNSEEDED"}'::jsonb;END IF;
 RETURN jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=r.k) THEN 'BODY_RETAINED' WHEN EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=r.k) THEN 'EXISTING_ATTEMPT_HELD_NO_REISSUE' ELSE 'ELIGIBLE' END,'request_key',r.k);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_claim(aid bigint,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;a record;p record;b record;r record;tid uuid;at uuid;tok text;pin record;taskrow record;ex bigint;BEGIN
 IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RETURN '{"state":"BUSY"}'::jsonb;END IF;
 d:=population_top3000_202608_202609_v1.oq6_guard(aid); -- Controls are always first.
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
 IF (d->>'not_after')::timestamptz<=clock_timestamp()+interval '45 seconds' THEN RETURN '{"state":"QUIET_SOURCE_TIME_BOUND"}'::jsonb;END IF;
 SELECT * INTO STRICT pin FROM population_top3000_202608_202609_v1.oq6_pin WHERE id;
 IF wsha IS DISTINCT FROM pin.worker_sha THEN RAISE EXCEPTION 'OQ6_DEPLOYED_CODE_CHANGED';END IF;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
 SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
 IF a.next_provider_at>clock_timestamp() OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_job WHERE status='LEASED' AND lease_until>clock_timestamp()) THEN RETURN '{"state":"QUIET_SHARED_PROVIDER_WAIT"}'::jsonb;END IF;
 SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_START_REQUIRED';END IF;
 IF b.checkpoint=201 THEN RETURN '{"state":"COMPLETE"}'::jsonb;END IF;
 SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.ov4_request WHERE ordinal=b.checkpoint;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(r.case_refs) q(cp) WHERE NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 ap WHERE ap.content->>'company_id'=cp->>'company_id' AND ap.ticker=r.r->>'ticker' AND ap.point_date=DATE '2026-08-03' AND ap.eligible AND ap.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND ap.record_sha256=cp->>'expected_anchor_sha' AND ap.record_sha256=encode(sha256(convert_to(ap.content::text,'UTF8')),'hex'))) THEN RAISE EXCEPTION 'OQ6_STALE_COMPANY_ANCHOR_PIN';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ov4_cap WHERE k=r.k) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=r.k) THEN RETURN jsonb_build_object('state','EXISTING_ATTEMPT_HELD_NO_REISSUE','request_key',r.k);END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cp JOIN population_top3000_202608_202609_v1.pipeline_event e ON e.event_id=cp.admission WHERE e.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=100 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_SOURCE_BOUND"}'::jsonb;END IF;
 IF (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND (relname LIKE 'oq6_%' OR relname LIKE 'ov4_%'))+3145728>33554432 THEN RETURN '{"state":"FINITE_RELATION_WAIT"}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cc JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=cc.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=200 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_HTTP_BOUND"}'::jsonb;END IF;
 IF a.provider_requests>=a.max_provider_requests OR a.http_invocations>=a.max_http_invocations OR a.stored_bytes+a.reserved_bytes+1048576>a.max_source_bytes OR (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE admission=aid)>=100 OR ((SELECT bytes FROM population_top3000_202608_202609_v1.oq6_spool_budget WHERE id)+(SELECT coalesce(sum(octet_length(body)),0) FROM population_top3000_202608_202609_v1.ov4_spool)+(SELECT coalesce(sum(l.reserved_bytes),0) FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.oq6_cap c USING(attempt_id) WHERE l.released_at IS NULL)+1048576)>33554432 OR (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m'))+3145728>=(p.budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint THEN RETURN '{"state":"FINITE_RESOURCE_WAIT"}'::jsonb;END IF;
 SELECT * INTO STRICT taskrow FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=b.task_id FOR UPDATE;
 IF taskrow.status<>'BLOCKED' OR taskrow.executions>=taskrow.max_executions OR b.last_request_id IS NULL THEN RAISE EXCEPTION 'OQ6_NATIVE_TASK_EXECUTION_OR_DISPATCH_REQUIRED';END IF;
 IF taskrow.blocker_code='OQ6_RETAINED_SOURCE_QUALITY_HOLD' THEN
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task tt JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=(tt.payload->>'oq6_admission')::bigint WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=(SELECT least(50,(se.details->>'maximum_new_tasks')::int) FROM population_top3000_202608_202609_v1.pipeline_event se JOIN population_top3000_202608_202609_v1.pipeline_event ce ON se.event_id=(ce.details->>'assignment_event_id')::bigint WHERE ce.event_id=(d->>'execution_claim_event_id')::bigint) THEN RETURN '{"state":"FINITE_NEW_TASK_BOUND"}'::jsonb;END IF;
 tid:=gen_random_uuid();
 INSERT INTO population_top3000_202608_202609_v1.pipeline_task(task_id,operation_key,family_id,stage,partition_key,payload,input_versions,status,max_executions,blocker_code,resumption_condition) VALUES(tid,'oq6:'||aid||':after-quality:'||b.checkpoint,'REF01','ACQUIRE','oq6-private-native:'||aid||':'||b.checkpoint,jsonb_build_object('source_admission',aid,'oq6_admission',aid,'execution_binding','REVIEWED_PRIVATE_NATIVE_FUNCTION'),taskrow.input_versions,'BLOCKED',100,'OQ6_PRIVATE_NATIVE_ROUTE','{"route":"oq6_wake"}');
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET task_id=tid WHERE admission=aid;SELECT * INTO b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid;SELECT * INTO taskrow FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=tid FOR UPDATE;
 END IF;
 ex:=taskrow.executions+1;
 at:=gen_random_uuid();tok:=gen_random_uuid()::text||gen_random_uuid()::text;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256,request_id) VALUES(at,b.task_id,ex,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)')),'UTF8')),'hex'),b.last_request_id);
 INSERT INTO population_top3000_202608_202609_v1.oq6_cap VALUES(r.k,at,aid,encode(sha256(convert_to(tok,'UTF8')),'hex'),wsha,clock_timestamp());
 INSERT INTO population_top3000_202608_202609_v1.pipeline_provider_lease(attempt_id,provider,reserved_bytes,reserved_usd) VALUES(at,'Massive',1048576,0);
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=at,lease_until=least(clock_timestamp()+interval '90 seconds',(d->>'not_after')::timestamptz),executions=ex,owner_fence=3,stop_generation=1,started_at=coalesce(started_at,clock_timestamp()) WHERE task_id=b.task_id;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET provider_requests=provider_requests+1,http_invocations=http_invocations+1,reserved_bytes=reserved_bytes+1048576,next_provider_at=clock_timestamp()+interval '15 seconds' WHERE singleton;
 RETURN jsonb_build_object('state','CLAIMED','token',tok,'request',r.r||jsonb_build_object('request_key',r.k,'request_manifest_sha256',d->>'request_manifest_sha256','scope_sha256',d->>'scope_sha256','request_state','ADMITTED'));
END;$$;
-- Independent committed RPC: no control, task, attempt or provider-lease lock.
-- Capability permits only retaining the already reserved response. It cannot issue HTTP,
-- release reservations, normalize, advance a task or qualify facts.
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_spool_save(k0 text,tok text,receipt text,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE c record;j jsonb;b bytea;h text;n int;old record;BEGIN
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p CROSS JOIN population_top3000_202608_202609_v1.oq6_pin pin WHERE a.singleton AND p.singleton AND pin.id AND a.owner_id='top3000-completion-20261024-root-5db48b32d103' AND a.owner_fence=3 AND a.stop_generation=1 AND a.enabled AND NOT a.stopped AND a.hold_reason IS NULL AND p.enabled AND p.deadline>clock_timestamp() AND a.admitted_until>clock_timestamp() AND p.expected_owner_id=a.owner_id AND p.expected_owner_fence=3 AND p.expected_stop_generation=1 AND a.scope_sha256=p.scope_sha256 AND a.scope_sha256='8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' AND p.budget_evidence#>>'{cohort_selection_policy,policy_sha256}'='3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb' AND pin.worker_sha=wsha AND pin.worker_sha=c.worker_sha) THEN RAISE EXCEPTION 'OQ6_SPOOL_CURRENT_OWNER_STOP_POLICY_CODE_REQUIRED';END IF;
 IF c.token_sha IS DISTINCT FROM encode(sha256(convert_to(tok,'UTF8')),'hex') OR c.worker_sha IS DISTINCT FROM wsha THEN RAISE EXCEPTION 'OQ6_SPOOL_CAPABILITY_REJECTED';END IF;
 IF octet_length(receipt)>1500000 THEN RAISE EXCEPTION 'OQ6_RECEIPT_BOUND';END IF;j:=receipt::jsonb;b:=decode(j->>'body_base64','base64');n:=octet_length(b);h:=encode(sha256(b),'hex');
 IF n>1048576 OR j->>'sha256' IS DISTINCT FROM h OR j->>'bytes' IS DISTINCT FROM n::text OR j->>'physical_http_count' IS DISTINCT FROM '1' OR j->>'representation' IS DISTINCT FROM 'FETCH_RESPONSE_BODY_BYTES_NOT_ORIGINAL_HTTP_WIRE' THEN RAISE EXCEPTION 'OQ6_SOURCE_HASH_OR_BOUND_REJECTED';END IF;
 PERFORM 1 FROM population_top3000_202608_202609_v1.oq6_spool_budget WHERE id FOR UPDATE;
 SELECT * INTO old FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=k0;
 IF FOUND THEN IF old.body IS DISTINCT FROM b OR old.receipt IS DISTINCT FROM j-'body_base64' THEN RAISE EXCEPTION 'OQ6_IMMUTABLE_SPOOL_CONFLICT';END IF;RETURN jsonb_build_object('state','BODY_ALREADY_RETAINED','sha256',h);END IF;
 UPDATE population_top3000_202608_202609_v1.oq6_spool_budget SET bytes=bytes+n WHERE id AND bytes+n<=33554432;IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_SPOOL_CUMULATIVE_BOUND';END IF;
 INSERT INTO population_top3000_202608_202609_v1.oq6_spool VALUES(k0,b,h,(j->>'http_status')::int,j-'body_base64',clock_timestamp());
 RETURN jsonb_build_object('state','BODY_RETAINED','sha256',h,'original_historical_receipt_proven',false);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_consume(k0 text,aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;c record;s record;r record;a record;t record;b record;l record;doc jsonb;v jsonb;h text;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0 AND admission=aid;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE attempt_id=c.attempt_id FOR UPDATE;
 IF a.outcome='COMPLETE' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_point p JOIN population_top3000_202608_202609_v1.pipeline_commit m ON m.attempt_id=a.attempt_id AND m.output_sha256=p.sha WHERE p.k=k0 AND p.sha=encode(sha256(convert_to(p.point::text,'UTF8')),'hex')) THEN RETURN jsonb_build_object('state','POINT_ALREADY_RETAINED','request_key',k0);END IF;
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=a.task_id FOR UPDATE;
 IF a.outcome='BLOCKED' AND t.blocker_code='OQ6_RETAINED_SOURCE_QUALITY_HOLD' AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease lease_row WHERE lease_row.attempt_id=a.attempt_id AND lease_row.released_at IS NOT NULL AND lease_row.outcome='KNOWN_RESPONSE_RETAINED_QUALITY_HOLD') THEN RETURN '{"state":"BODY_RETAINED_QUALITY_ALREADY_SETTLED","automatic_retry":false,"no_listing_inferred":false}'::jsonb;END IF;
 IF a.adapter_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(to_regprocedure('population_top3000_202608_202609_v1.oq6_claim(bigint,text)')),'UTF8')),'hex') OR a.owner_fence<>3 OR a.stop_generation<>1 OR t.attempt_id IS DISTINCT FROM a.attempt_id OR a.execution_number IS DISTINCT FROM t.executions OR t.lease_until IS NULL OR t.lease_until<=clock_timestamp() OR a.request_id IS NULL OR c.worker_sha IS DISTINCT FROM d->>'worker_sha256' THEN RAISE EXCEPTION 'OQ6_ATTEMPT_TASK_CODE_BINDING';END IF;
 SELECT * INTO STRICT s FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=k0;
 SELECT * INTO STRICT r FROM population_top3000_202608_202609_v1.ov4_request WHERE k=k0;
 IF s.sha IS DISTINCT FROM encode(sha256(s.body),'hex') THEN RAISE EXCEPTION 'OQ6_SOURCE_CHANGED';END IF;
 IF a.outcome='COMPLETE' THEN RETURN jsonb_build_object('state','POINT_ALREADY_RETAINED','request_key',k0);END IF;
 IF a.outcome<>'RUNNING' OR t.status<>'LEASED' THEN RAISE EXCEPTION 'OQ6_ATTEMPT_NOT_RUNNING';END IF;
 IF s.status<>200 THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'HTTP_ERROR');END IF;
 BEGIN doc:=convert_from(s.body,'UTF8')::jsonb;EXCEPTION WHEN OTHERS THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'ENCODING_OR_JSON');END;
 IF doc->>'status' IS DISTINCT FROM 'OK' OR jsonb_typeof(doc->'results') IS DISTINCT FROM 'object' OR doc#>>'{results,ticker}' IS DISTINCT FROM r.r->>'ticker' OR nullif(doc->>'next_url','') IS NOT NULL THEN RETURN population_top3000_202608_202609_v1.oq6_settle_quality(k0,aid,'IDENTITY_OR_STATUS');END IF;
 v:=jsonb_build_object('request',r.r,'case_refs',r.case_refs,'source_record',doc->'results','source_sha256',s.sha,'request_sha256',r.request_sha,'evidence_semantics','DATE_QUALIFIED_VENDOR_OVERVIEW_POINT_NOT_INTERVAL_V6','original_historical_receipt_proven',false,'intervals_qualified',false,'family_accepted',false);h:=encode(sha256(convert_to(v::text,'UTF8')),'hex');
 INSERT INTO population_top3000_202608_202609_v1.oq6_point VALUES(k0,v,h);
 SELECT * INTO STRICT l FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE attempt_id=a.attempt_id AND released_at IS NULL FOR UPDATE;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET reserved_bytes=reserved_bytes-l.reserved_bytes,stored_bytes=stored_bytes+octet_length(s.body) WHERE singleton AND reserved_bytes>=l.reserved_bytes;IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_COUNTER_RESERVATION_MISMATCH';END IF;
 UPDATE population_top3000_202608_202609_v1.pipeline_provider_lease SET released_at=clock_timestamp(),received_bytes=octet_length(s.body),outcome='NATIVE_SINGLE_HTTP_BODY_RETAINED' WHERE attempt_id=a.attempt_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_commit(attempt_id,task_id,commit_key,output_sha256,receipt,new_committed_units) VALUES(a.attempt_id,a.task_id,'oq6-point:'||k0,h,jsonb_build_object('execution_binding','REVIEWED_PRIVATE_NATIVE_FUNCTION','worker_sha256',c.worker_sha,'source_sha256',s.sha,'point_only',true),1);
 UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET outcome='COMPLETE',ended_at=clock_timestamp() WHERE attempt_id=a.attempt_id;
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET checkpoint=(SELECT next_ordinal FROM population_top3000_202608_202609_v1.oq6_population()) WHERE admission=aid RETURNING * INTO b;
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status=CASE WHEN b.checkpoint=201 OR t.executions>=t.max_executions THEN 'COMPLETE' ELSE 'BLOCKED' END,blocker_code=CASE WHEN b.checkpoint=201 OR t.executions>=t.max_executions THEN NULL ELSE 'OQ6_PRIVATE_NATIVE_CONTINUATION' END,resumption_condition=jsonb_build_object('route','oq6_claim','admission',aid,'next_ordinal',b.checkpoint),checkpoint=jsonb_build_object('next_ordinal',b.checkpoint),useful_committed_units=useful_committed_units+1,last_useful_progress_at=clock_timestamp(),completed_at=CASE WHEN b.checkpoint=201 OR t.executions>=t.max_executions THEN clock_timestamp() ELSE NULL END WHERE task_id=a.task_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,task_id,attempt_id,details) VALUES('REF01_OVERVIEW_CONTINUATION_REQUIRED_V6',a.task_id,a.attempt_id,jsonb_build_object('admission',aid,'checkpoint',b.checkpoint,'existing_executor','automation:6adc2c96db348191bca7cf4eacfdac32','route','oq6_claim','no_automatic_http_retry',true));
 PERFORM population_top3000_202608_202609_v1.oq6_dispatch(aid);
 RETURN jsonb_build_object('state','POINT_RETAINED','request_key',k0,'record_sha256',h,'next_ordinal',b.checkpoint,'family_accepted',false);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_unknown(k0 text,tok text,why text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE c record;BEGIN
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0;
 IF c.token_sha IS DISTINCT FROM encode(sha256(convert_to(tok,'UTF8')),'hex') THEN RAISE EXCEPTION 'OQ6_CAPABILITY_REQUIRED';END IF;
 -- No lease release or retry; uncertain external evidence remains separate.
 RETURN jsonb_build_object('state','UNKNOWN_EXTERNAL_OUTCOME_HELD','request_key',k0,'automatic_retry',false,'lease_released',false,'reason',left(why,128));
END;$$;

CREATE FUNCTION population_top3000_202608_202609_v1.oq6_dispatch(aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;b record;rid bigint;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid FOR UPDATE;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=100 THEN RETURN '{"state":"FINITE_CLAIM_DISPATCH_BOUND"}'::jsonb;END IF;
 IF b.checkpoint=201 OR b.wake_ordinal>=b.checkpoint OR b.dispatches>=100 OR (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap WHERE admission=aid)>=100 THEN RETURN '{"state":"FINITE_TRANCHE_COMPLETE_OR_HELD","automatic_retry":false}'::jsonb;END IF;
 IF (SELECT coalesce(sum(bb.dispatches),0) FROM population_top3000_202608_202609_v1.oq6_batch bb JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=bb.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')+(SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_cap cc JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=cc.admission WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=200 THEN RETURN '{"state":"FINITE_EXECUTION_CLAIM_HTTP_BOUND"}'::jsonb;END IF;
 IF (SELECT http_invocations>=max_http_invocations FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) THEN RETURN '{"state":"HTTP_CAP_HELD"}'::jsonb;END IF;
 SELECT net.http_post(url:='https://oxzabweahkoimtevbbny.supabase.co/functions/v1/population-top3000-overview-v6',headers:='{"Content-Type":"application/json"}'::jsonb,body:=jsonb_build_object('admission_event_id',aid,'wake_token',b.wake_token),timeout_milliseconds:=55000) INTO rid;
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET dispatches=dispatches+1,wake_ordinal=checkpoint,last_request_id=rid WHERE admission=aid;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET http_invocations=http_invocations+1 WHERE singleton;
 RETURN jsonb_build_object('state','ASYNC','request_id',rid,'dispatch_http',1,'provider_http',0);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_wake(aid bigint,tok text,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE b record;BEGIN
 SELECT * INTO STRICT b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid;
 IF b.wake_token IS DISTINCT FROM tok OR (SELECT worker_sha FROM population_top3000_202608_202609_v1.oq6_pin WHERE id) IS DISTINCT FROM wsha THEN RAISE EXCEPTION 'OQ6_WAKE_AUTH_OR_CODE_REJECTED';END IF;
 RETURN population_top3000_202608_202609_v1.oq6_claim(aid,wsha);
END;$$;
CREATE FUNCTION population_top3000_202608_202609_v1.oq6_start(aid bigint) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;tid uuid;n int;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF (SELECT unknown FROM population_top3000_202608_202609_v1.oq6_population())>0 THEN RETURN '{"state":"UNKNOWN_CAPABILITY_HOLD_NO_REISSUE"}'::jsonb;END IF;
 IF (SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task tt JOIN population_top3000_202608_202609_v1.pipeline_event ee ON ee.event_id=(tt.payload->>'oq6_admission')::bigint WHERE ee.details->>'execution_claim_event_id'=d->>'execution_claim_event_id')>=(SELECT least(50,(se.details->>'maximum_new_tasks')::int) FROM population_top3000_202608_202609_v1.pipeline_event se JOIN population_top3000_202608_202609_v1.pipeline_event ce ON se.event_id=(ce.details->>'assignment_event_id')::bigint WHERE ce.event_id=(d->>'execution_claim_event_id')::bigint) THEN RAISE EXCEPTION 'OQ6_EXECUTION_CLAIM_TASK_BOUND';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid) THEN RETURN '{"state":"ALREADY_STARTED_NO_DUPLICATE_WAKE"}'::jsonb;END IF;
 SELECT next_ordinal INTO n FROM population_top3000_202608_202609_v1.oq6_population();
 IF n=201 THEN RETURN jsonb_build_object('state','ALL_REQUESTS_DISPOSITIONED_QUALITY_HOLDS_REMAIN','tasks_created',0,'family_accepted',false,'point_facts_qualified',false);END IF;
 tid:=gen_random_uuid();
 INSERT INTO population_top3000_202608_202609_v1.pipeline_task(task_id,operation_key,family_id,stage,partition_key,payload,input_versions,status,max_executions,blocker_code,resumption_condition) VALUES(tid,'oq6:'||aid,'REF01','ACQUIRE','oq6-private-native:'||aid,jsonb_build_object('execution_binding','REVIEWED_PRIVATE_NATIVE_FUNCTION','source_admission',aid,'oq6_admission',aid),jsonb_build_object('manifest',d->>'request_manifest_sha256','worker',d->>'worker_sha256','policy','3e49d661fcdb8533e5ce88a85689b41e9dde71eeae2dc8578c9e31f9ae1738bb'),'BLOCKED',100,'OQ6_PRIVATE_NATIVE_ROUTE','{"route":"oq6_wake"}');
 INSERT INTO population_top3000_202608_202609_v1.oq6_batch(admission,task_id,checkpoint) VALUES(aid,tid,n);
 RETURN population_top3000_202608_202609_v1.oq6_dispatch(aid);
END;$$;


CREATE FUNCTION population_top3000_202608_202609_v1.oq6_auth(aid bigint,tok text,wsha text) RETURNS boolean LANGUAGE sql STABLE SET search_path='pg_catalog' AS $$SELECT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_batch b CROSS JOIN population_top3000_202608_202609_v1.oq6_pin p WHERE b.admission=aid AND b.wake_token=tok AND p.id AND p.worker_sha=wsha)$$;


CREATE FUNCTION population_top3000_202608_202609_v1.oq6_defer(aid bigint,tok text,wsha text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE b record;BEGIN
 PERFORM population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT b FROM population_top3000_202608_202609_v1.oq6_batch WHERE admission=aid FOR UPDATE;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_quality WHERE disposition->>'continuation_eligible' IS DISTINCT FROM 'true') THEN RETURN '{"state":"KNOWN_PROVIDER_OR_CONTRACT_HOLD"}'::jsonb;END IF;
 IF b.wake_token IS DISTINCT FROM tok OR NOT population_top3000_202608_202609_v1.oq6_auth(aid,tok,wsha) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap c JOIN population_top3000_202608_202609_v1.ov4_request r ON r.k=c.k WHERE r.ordinal=b.checkpoint) THEN RAISE EXCEPTION 'OQ6_ONLY_PROVEN_NO_HTTP_WAIT_MAY_DEFER';END IF;
 -- No provider capability was issued. A bounded new internal wake is safe; each wake
 -- still consumes one of100 dispatches and the global HTTP budget. Source retries forbidden.
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET wake_ordinal=0 WHERE admission=aid;
 RETURN population_top3000_202608_202609_v1.oq6_dispatch(aid);
END;$$;



CREATE FUNCTION population_top3000_202608_202609_v1.oq6_settle_quality(k0 text,aid bigint,why text) RETURNS jsonb LANGUAGE plpgsql SET search_path='pg_catalog' AS $$
DECLARE d jsonb;c record;s record;a record;t record;l record;BEGIN
 d:=population_top3000_202608_202609_v1.oq6_guard(aid);
 SELECT * INTO STRICT c FROM population_top3000_202608_202609_v1.oq6_cap WHERE k=k0 AND admission=aid;
 SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE attempt_id=c.attempt_id FOR UPDATE;
 SELECT * INTO STRICT t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=a.task_id FOR UPDATE;
 SELECT * INTO STRICT s FROM population_top3000_202608_202609_v1.oq6_spool WHERE k=k0;
 IF why NOT IN('HTTP_ERROR','ENCODING_OR_JSON','IDENTITY_OR_STATUS') OR s.sha IS DISTINCT FROM encode(sha256(s.body),'hex') OR a.outcome<>'RUNNING' OR t.attempt_id IS DISTINCT FROM a.attempt_id OR a.execution_number<>t.executions OR t.owner_fence<>3 OR t.stop_generation<>1 OR a.owner_fence<>3 OR a.stop_generation<>1 THEN RAISE EXCEPTION 'OQ6_KNOWN_COMPLETE_RESPONSE_SETTLEMENT_BINDING';END IF;
 SELECT * INTO STRICT l FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE attempt_id=a.attempt_id AND released_at IS NULL FOR UPDATE;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET reserved_bytes=reserved_bytes-l.reserved_bytes,stored_bytes=stored_bytes+octet_length(s.body) WHERE singleton AND reserved_bytes>=l.reserved_bytes;IF NOT FOUND THEN RAISE EXCEPTION 'OQ6_COUNTER_RESERVATION_MISMATCH';END IF;
 UPDATE population_top3000_202608_202609_v1.pipeline_provider_lease SET released_at=clock_timestamp(),received_bytes=octet_length(s.body),actual_usd=NULL,outcome='KNOWN_RESPONSE_RETAINED_QUALITY_HOLD' WHERE attempt_id=a.attempt_id;
 UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET outcome='BLOCKED',ended_at=clock_timestamp() WHERE attempt_id=a.attempt_id;
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='BLOCKED',lease_until=NULL,blocker_code='OQ6_RETAINED_SOURCE_QUALITY_HOLD',resumption_condition=jsonb_build_object('request_key',k0,'source_sha256',s.sha,'quality_reason',why,'required_action','Independent retained-source quality review; no automatic source retry','no_listing_inferred',false) WHERE task_id=a.task_id;

 INSERT INTO population_top3000_202608_202609_v1.oq6_quality(k,origin,source_sha,disposition,sha)
 SELECT k0,'NEW',s.sha,v,encode(sha256(convert_to(v::text,'UTF8')),'hex') FROM (SELECT jsonb_build_object('origin','NEW','kind','KNOWN_HTTP_RESPONSE_QUALITY_HOLD','http_status',s.status,'source_sha256',s.sha,'quality_reason',why,'continuation_eligible',population_top3000_202608_202609_v1.oq6_continuable404(s.status,s.body),'point_facts_qualified',false,'absence_inferred',false,'inactive_inferred',false,'intervals_qualified',false,'family_accepted',false) v) q;
 UPDATE population_top3000_202608_202609_v1.oq6_batch SET checkpoint=(SELECT next_ordinal FROM population_top3000_202608_202609_v1.oq6_population()) WHERE admission=aid;
 PERFORM population_top3000_202608_202609_v1.oq6_dispatch(aid);
 RETURN jsonb_build_object('state','BODY_RETAINED_QUALITY_HOLD','physical_lease_released',true,'actual_usd',NULL,'automatic_retry',false,'no_listing_inferred',false,'point_facts_committed',false);
END;$$;

CREATE FUNCTION population_top3000_202608_202609_v1.oq6_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path='pg_catalog' AS $$BEGIN RAISE EXCEPTION 'OQ6_APPEND_ONLY_IMMUTABLE_EVIDENCE';END;$$;
