CREATE TRIGGER oq6_cap_immutable BEFORE UPDATE OR DELETE ON population_top3000_202608_202609_v1.oq6_cap FOR EACH ROW EXECUTE FUNCTION population_top3000_202608_202609_v1.oq6_immutable();
CREATE TRIGGER oq6_spool_immutable BEFORE UPDATE OR DELETE ON population_top3000_202608_202609_v1.oq6_spool FOR EACH ROW EXECUTE FUNCTION population_top3000_202608_202609_v1.oq6_immutable();
CREATE TRIGGER oq6_point_immutable BEFORE UPDATE OR DELETE ON population_top3000_202608_202609_v1.oq6_point FOR EACH ROW EXECUTE FUNCTION population_top3000_202608_202609_v1.oq6_immutable();
CREATE TRIGGER oq6_pin_immutable BEFORE UPDATE OR DELETE ON population_top3000_202608_202609_v1.oq6_pin FOR EACH ROW EXECUTE FUNCTION population_top3000_202608_202609_v1.oq6_immutable();

DO $$DECLARE r record;BEGIN FOR r IN SELECT oid::regclass rel FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relname LIKE 'oq6_%' AND relkind='r' LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',r.rel);EXECUTE format('REVOKE ALL ON %s FROM PUBLIC,anon,authenticated',r.rel);END LOOP;FOR r IN SELECT oid::regprocedure fn FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE 'oq6_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',r.fn);END LOOP;END;$$;
$ov4ddl$;
 PERFORM population_top3000_202608_202609_v1.oq6_seed('b7d9783a20f8a6a94325eaf907aee2bd5d439184ad5e3b9ca3d223730c2215c4');
 new_manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
 SELECT jsonb_object_agg(proname,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex')) INTO hashes FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname LIKE 'oq6_%';
 IF new_manifest IS DISTINCT FROM rb->'prospective_manifest' OR new_manifest IS DISTINCT FROM rv->'reviewed_code_manifest' OR hashes IS DISTINCT FROM rb->'function_hashes' OR (SELECT count(*) FROM population_top3000_202608_202609_v1.ov4_request)<>200 OR (SELECT count(*) FROM population_top3000_202608_202609_v1.oq6_quality)<>1 OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_cap) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_spool) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_point) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.oq6_batch) THEN RAISE EXCEPTION 'OQ6_POSTINSTALL_MANIFEST_OR_ZERO_SOURCE_BOUND';END IF;
 IF (SELECT sum(pg_total_relation_size(oid)) FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relname LIKE 'oq6_%')>33554432 THEN RAISE EXCEPTION 'OQ6_IMPLEMENTATION_RELATION_BOUND';END IF;
 SELECT jsonb_build_object('ac',to_jsonb(ac),'pc',to_jsonb(pc),'tasks',(SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_task),'attempts',(SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_attempt),'commits',(SELECT count(*) FROM population_top3000_202608_202609_v1.pipeline_commit),'source_docs',(SELECT count(*) FROM population_top3000_202608_202609_v1.source_document),'source_jobs',(SELECT count(*) FROM population_top3000_202608_202609_v1.acquisition_job),'oldcap',(SELECT jsonb_agg(to_jsonb(c)) FROM population_top3000_202608_202609_v1.ov4_cap c),'oldbody',(SELECT jsonb_agg(to_jsonb(s)) FROM population_top3000_202608_202609_v1.ov4_spool s),'oldattempt',(SELECT jsonb_agg(to_jsonb(a)) FROM population_top3000_202608_202609_v1.pipeline_attempt a WHERE attempt_id IN(SELECT attempt_id FROM population_top3000_202608_202609_v1.ov4_cap)),'oldtask',(SELECT jsonb_agg(to_jsonb(t)) FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id IN(SELECT task_id FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE attempt_id IN(SELECT attempt_id FROM population_top3000_202608_202609_v1.ov4_cap))),'oldlease',(SELECT jsonb_agg(to_jsonb(l)) FROM population_top3000_202608_202609_v1.pipeline_provider_lease l WHERE attempt_id IN(SELECT attempt_id FROM population_top3000_202608_202609_v1.ov4_cap))) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
 IF before_state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'OQ6_INSTALL_ALTERED_EXISTING_COUNTER_TASK_OR_SOURCE';END IF;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_IMPLEMENTATION_INTEGRATED_V5',ctl||jsonb_build_object('actor','automation:6adc2c96db348191bca7cf4eacfdac32','assignment_event_id',49964,'claim_event_id',50296,'independent_review_event_id',review_id,'runtime_rollback_event_id',rollback_id,'negative_proof_event_id',negative_proof_id,'deployed_worker_proof_event_id',cloud_id,'code_manifest',new_manifest,'sql_sha256',rv->>'sql_sha256','worker_source_sha256',cloud->>'worker_source_sha256','edge_ezbr_sha256',cloud->>'edge_ezbr_sha256','result','INTEGRATED_WAITING_FOR_SOURCE_ADMISSION','original_private_requests',200,'known_quality_dispositions',1,'unattempted_requests',199,'tasks_created',0,'source_bodies',0,'points',0,'provider_calls',0,'source_http',0,'family_accepted',false)) RETURNING event_id INTO integ;
