 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RECOVERY_DELEGATION_QUALIFIED_V1',old_rec||jsonb_build_object('actor','automation:6adc2c96db348191bca7cf4eacfdac32','requalified_at',clock_timestamp(),'expires_at',ctl->>'not_after','not_after',ctl->>'not_after','code_manifest',new_manifest,'reviewed_manifest_sha256',encode(sha256(convert_to(new_manifest::text,'UTF8')),'hex'),'independent_review_event_id',review_id,'runtime_rollback_proof_event_id',rollback_id,'integration_event_id',integ,'superseded_policy_event_id',old_rec_id,'restarts_already_used_under_authority',restart_count,'qualification_reason','Independently reviewed separately versioned known404 disposition and finite native continuation; old15functions, heldsource rows and accounting preserved; source activation still unadmitted; quality/lifecycle/family holds retained')) RETURNING event_id,details INTO qual,new_rec;
